def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full-width / full-height separator lines.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    nr, nc = len(row_spans), len(col_spans)

    # Leftmost tile in each band names its color; any other nonempty tile
    # supplies the common shape mask.
    labels = []
    for r0, r1 in row_spans:
        counts = {}
        for r in range(r0, r1):
            for c in range(col_spans[0][0], col_spans[0][1]):
                v = grid[r][c]
                if v:
                    counts[v] = counts.get(v, 0) + 1
        labels.append(max(counts, key=counts.get))

    mask = None
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            if ci == 0:
                continue
            cells = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if any(v != 0 for row in cells for v in row):
                mask = [[1 if v != 0 else 0 for v in row] for row in cells]
                break
        if mask is not None:
            break
    if mask is None:
        raise ValueError('No shape template found')

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            for dr, r in enumerate(range(r0, r1)):
                for dc, c in enumerate(range(c0, c1)):
                    out[r][c] = labels[ri] if mask[dr][dc] else 0
    return out
